#!/usr/bin/perl
use strict; use warnings;
my $C = '/workspace/dataset/test11_executable';
my $R = '/output/test11';

# run($bin, @args) -> (stdout_bytes, exitcode)
sub run {
  my ($bin, @args) = @_;
  my $tmp = "/tmp/wf-spec-5/.o.$$";
  my $pid = fork(); die "fork" unless defined $pid;
  if ($pid == 0) {
    open(STDOUT, '>', $tmp) or exit 127;
    open(STDERR, '>', '/dev/null');
    exec { $bin } ($bin, @args) or exit 127;
  }
  waitpid($pid, 0);
  my $st = $?;
  local $/; open(my $fh, '<', $tmp) or return ('', -1);
  binmode $fh; my $out = <$fh>; close $fh; unlink $tmp;
  $out = '' unless defined $out;
  return ($out, $st >> 8);
}

# field 6 of the single output line; only valid when no arg contains space/newline
sub f6 {
  my (@args) = @_;
  my ($o, $e) = run($C, @args);
  $o =~ s/\n\z//;
  my @f = split(/ /, $o, -1);
  return scalar(@f) == 11 ? $f[5] : "PARSE_ERR(".scalar(@f).")";
}

sub cmpboth {
  my (@args) = @_;
  my ($co, $ce) = run($C, @args);
  my ($ro, $re) = run($R, @args);
  return ($co eq $ro && $ce == $re) ? 1 : 0;
}

sub dump_diff {
  my (@args) = @_;
  my ($co, $ce) = run($C, @args);
  my ($ro, $re) = run($R, @args);
  print "  C(exit=$ce): ", unpack("H*", $co), "\n";
  print "  R(exit=$re): ", unpack("H*", $ro), "\n";
}
1;
PERL
