require '/tmp/wf-spec-5/harness.pl';
# Exact binary search of the upper length boundary using 'a'
my $lo=1; my $hi=200;
# verify monotone assumption endpoints first
printf "len=1   f6=%s\n", f6('a' x 1);
printf "len=200 f6=%s\n", f6('a' x 200);
while ($hi - $lo > 1) {
  my $mid = int(($lo+$hi)/2);
  my $v = f6('a' x $mid);
  if ($v eq '1') { $lo = $mid } else { $hi = $mid }
}
print "BOUNDARY: last accepted len=$lo, first rejected len=$hi\n";
for my $n (0,1,2,$lo-1,$lo,$hi,$hi+1) {
  printf "  len=%-4d f6=%s\n", $n, f6('a' x $n);
}
